//! Native reset-button actions restore OUTPUT defaults through actual text.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.dom_attr(n,"id").is_some_and(|v|v.raw_units().is_none()&&v.as_str()==id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
fn click(app:&mut App,id:&str){let n=node(app,id);let r=app.page.controls.iter().find(|r|r.node==n).unwrap();let(x,y)=(r.x+r.width/2,app.content_top()+r.y+r.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);if let Some(page)=&app.scripting{assert_eq!(page.error_count(),0,"{}",page.report());}assert!(!app.failed,"{}",app.status);}
fn exercise(name:&str,setup:&str,check:&str){let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-output-reset-{name}-{}.html",std::process::id())));let source=format!(r#"<!doctype html><style>body{{margin:0}}output{{display:block;height:30px}}button{{width:120px;height:30px}}</style><form id=owner><output id=output>original</output><input id=field value=seed><button id=reset type=reset>Reset</button></form><form id=other><output id=unrelated>other default</output></form><output id=external form=owner>external default</output><button id=check type=button>Check</button><script>var output=document.getElementById('output'),owner=document.getElementById('owner'),external=document.getElementById('external'),unrelated=document.getElementById('unrelated');{setup}document.getElementById('check').onclick=function(e){{if(!e.isTrusted)throw 'native pointer event';{check}document.title='Output reset passed';}};</script>"#);std::fs::write(&file.0,source).unwrap();let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());click(&mut app,"reset");click(&mut app,"check");assert_eq!(app.document.title,"Output reset passed");}
#[test]
fn output_reset_native_pointer_restores_default_and_clears_override(){exercise("restore",r#"output.value='current';output.defaultValue='A\ud800z';var old=output.firstChild;"#,r#"if(output.value!=='A\ud800z'||output.defaultValue!==output.value||old.parentNode!==null||old.data!=='current'||output.firstChild===old)throw 'reset restores actual default';output.textContent='later';if(output.defaultValue!=='later')throw 'reset cleared override';"#);}
#[test]
fn output_reset_canceled_native_action_preserves_current_and_default(){exercise("canceled","output.value='current';output.defaultValue='saved';var old=output.firstChild;owner.onreset=function(e){e.preventDefault();};","if(output.value!=='current'||output.defaultValue!=='saved'||output.firstChild!==old)throw 'canceled reset changed output';");}
#[test]
fn output_reset_current_exact_form_owner_and_reset_handler_mutation(){exercise("owner","output.value='current';external.value='external current';unrelated.value='other current';owner.onreset=function(){output.defaultValue='handler default';external.defaultValue='handler external';};","if(output.value!=='handler default'||external.value!=='handler external'||unrelated.value!=='other current'||unrelated.defaultValue!=='other default')throw 'current owner and reset handler';output.defaultValue='next';external.defaultValue='next external';if(output.value!=='next'||external.value!=='next external')throw 'both outputs returned to default mode';");}

#[test]
fn output_reset_scripting_disabled_flattens_real_children_without_interpreter(){let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-output-reset-disabled-{}.html",std::process::id())));std::fs::write(&file.0,"<form id=owner><output id=output>A<span hidden>B</span>C</output><input id=field value=seed><button id=reset type=reset>Reset</button></form>").unwrap();let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(false);app.open(&file.0);assert!(app.scripting.is_none());let output=node(&app,"output");let old=app.document.nodes[output].children.clone();let field=node(&app,"field");app.forms.script_set_value(field,"edited").unwrap();click(&mut app,"reset");assert!(app.scripting.is_none());assert_eq!(app.forms.controls[&field].value.text(),"seed");assert_eq!(app.document.nodes[output].children.len(),1);let fresh=app.document.nodes[output].children[0];assert!(!old.contains(&fresh));assert!(matches!(&app.document.nodes[fresh].kind,crate::html::NodeKind::Text(text)if text=="ABC"));}

#[test]
fn output_reset_observers_run_after_widget_reset_without_input_or_change(){exercise("observer","output.value='current';output.defaultValue='saved';var old=output.firstChild,records=[],events=0;output.oninput=function(){events++;};output.onchange=function(){events++;};document.getElementById('field').value='edited';var watch=new MutationObserver(function(batch){if(document.getElementById('field').value!=='seed'||output.defaultValue!==output.value)throw 'reset checkpoint before native widgets';for(var record of batch)records.push(record);});watch.observe(output,{childList:true});","if(events||records.length!==1||records[0].target!==output||records[0].removedNodes[0]!==old||records[0].addedNodes[0]!==output.firstChild||output.value!=='saved')throw 'native reset observer';");}
#[test]
fn output_reset_actual_app_paint_editor_link_and_page_identity(){let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-output-reset-paint-{}.html",std::process::id())));std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0;background:white}output{display:block;position:absolute;left:20px;top:20px;width:120px;height:32px;background:white;color:#112233}#reset{position:absolute;left:220px;top:20px;width:160px;height:32px}#check{position:absolute;left:220px;top:60px;width:160px;height:30px}#neighbor{position:absolute;left:220px;top:100px;width:180px;height:30px}#stable{position:absolute;left:420px;top:100px}#field{position:absolute;left:20px;top:140px}</style><form id=owner><label for=output>Result</label><output id=output for=seed name=result>WWWW</output><input id=field value=seed><button id=reset type=reset>Reset</button></form><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><button id=check type=button>Check</button><div id=destination></div><script>var output=document.getElementById('output'),owner=document.getElementById('owner'),labels=output.labels,tokens=output.htmlFor;output.value='ii';owner.onreset=function(){output.defaultValue='MMMM';};document.getElementById('check').onclick=function(e){if(!e.isTrusted||output.value!=='MMMM'||output.defaultValue!==output.value||output.labels!==labels||labels[0].control!==output||output.form!==owner||output.htmlFor!==tokens||tokens.value!=='seed'||output.name!=='result')throw 'reset text and associations';output.textContent='later';if(output.defaultValue!=='later')throw 'cleared native override';document.title='Painted reset passed';};</script>"#).unwrap();let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);let initial=app.draw();let top=app.content_top() as usize;let patch=|pixels:&[u32],width:usize|{let mut result=Vec::new();for y in top+20..top+52{result.extend_from_slice(&pixels[y*width+20..y*width+140]);}result};let before=patch(&initial.pixels,initial.width);let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");let field=node(&app,"field");app.forms.script_set_value(neighbor,"edited neighbor").unwrap();app.forms.script_set_value(field,"edited field").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;click(&mut app,"reset");let painted=app.draw();let after=patch(&painted.pixels,painted.width);assert_ne!(after,before,"actual reset text pixels");assert!(after.iter().any(|pixel|*pixel!=0xffffff));assert_eq!(app.forms.controls[&field].value.text(),"seed");let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);click(&mut app,"check");assert_eq!(app.document.title,"Painted reset passed");}
